-- | Positions and errors returned by parsers generated by peg-hs.
--
-- This is the module that application code imports alongside a generated
-- module. A generated module depends only on the @peg-runtime@ package and
-- exports an entry point for its start rule (ADR 0014):
--
-- > parse :: Text -> Either ParseError Expr
--
-- On failure, t'ParseError' holds the farthest position the parser reached
-- and the terminals it expected there, and 'renderParseError' turns it
-- into a one-line message:
--
-- @
-- import qualified Data.Text.IO as TIO
-- import System.IO (stderr)
-- import Calc (parse)            -- generated by: peg-hs gen Calc.hpeg
-- import Peg.Runtime (renderParseError)
--
-- main :: IO ()
-- main = do
--   src <- TIO.getContents
--   case parse src of
--     Left err -> TIO.hPutStrLn stderr (renderParseError err)  -- e.g. 1:4: expected \'+\', [0-9] or end of input
--     Right expr -> print expr
-- @
--
-- A grammar with labels (@e ^label@, ADR 0021) also gets recovering entry
-- points such as @parseRecover :: Text -> (Maybe Expr, [SyntaxError])@,
-- which report every error they recovered from as a t'SyntaxError'.
-- A grammar with @%syntax@ gets entry points that return a lossless syntax
-- tree; see "Peg.Runtime.Syntax".
--
-- Semantic actions can refer to the span of the input their alternative
-- consumed through the reserved binding @_span@, whose type is t'Span'.
module Peg.Runtime
  ( -- * Positions
    Pos (..)
  , Span (..)
    -- * Errors
  , ParseError (..)
  , Expected (..)
  , renderParseError
  , SyntaxError (..)
  ) where

import Peg.Runtime.Internal
